package com.group04.services;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*; import java.util.Optional; import org.junit.jupiter.api.*; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import com.group04.models.AuthDtos.*; import com.group04.utils.ApiException; import com.group04.dao.*; import com.group04.models.*;
class AuthServiceTest {
 CustomerRepository customers=mock(CustomerRepository.class);AdminRepository admins=mock(AdminRepository.class);RoleRepository roles=mock(RoleRepository.class);BCryptPasswordEncoder encoder=new BCryptPasswordEncoder(4);JwtService jwt=new JwtService("01234567890123456789012345678901",60000);AuthService service=new AuthService(customers,admins,roles,encoder,jwt);Role customerRole=new Role("CUSTOMER","Customer");Role adminRole=new Role("ADMIN","Admin");
 @BeforeEach void setup(){reset(customers);reset(admins);reset(roles);when(roles.findByName("CUSTOMER")).thenReturn(Optional.of(customerRole));when(customers.save(any())).thenAnswer(x->x.getArgument(0));}
 @Test void registerAlwaysCreatesCustomerWithBcryptAndNoHashInResponse(){var response=service.register(new RegisterRequest("Nguyen A","A@EXAMPLE.COM",null,"Strong@123"));var capture=org.mockito.ArgumentCaptor.forClass(Customer.class);verify(customers).save(capture.capture());assertEquals("CUSTOMER",capture.getValue().getAccountType());assertTrue(encoder.matches("Strong@123",capture.getValue().getPasswordHash()));assertFalse(response.toString().contains("Strong@123"));}
 @Test void duplicateAdminEmailIsConflict(){when(admins.existsByEmailIgnoreCase(anyString())).thenReturn(true);ApiException e=assertThrows(ApiException.class,()->service.register(new RegisterRequest("A","a@b.com",null,"Strong@123")));assertEquals(HttpStatus.CONFLICT,e.status());}
 @Test void lockedCustomerCannotLogin(){Customer c=new Customer(customerRole,"A","a@b.com",null,encoder.encode("Strong@123"));c.setStatus("LOCKED");when(customers.findByEmailIgnoreCase("a@b.com")).thenReturn(Optional.of(c));ApiException e=assertThrows(ApiException.class,()->service.login(new LoginRequest("a@b.com","Strong@123")));assertEquals(HttpStatus.FORBIDDEN,e.status());}
 @Test void wrongAdminPasswordIsUnauthorized(){Admin a=new Admin(adminRole,"Admin","admin@b.com",null,encoder.encode("Strong@123"));when(admins.findByEmailIgnoreCase("admin@b.com")).thenReturn(Optional.of(a));ApiException e=assertThrows(ApiException.class,()->service.login(new LoginRequest("admin@b.com","Wrong@123")));assertEquals(HttpStatus.UNAUTHORIZED,e.status());}
 @Test void resetCustomerPasswordAfterPhoneVerification(){Customer c=new Customer(customerRole,"A","a@b.com","0837777777",encoder.encode("OldPass@123"));when(customers.findByEmailIgnoreCase("a@b.com")).thenReturn(Optional.of(c));service.resetPassword(new ResetPasswordRequest("a@b.com","0837777777","NewPass@123"));assertTrue(encoder.matches("NewPass@123",c.getPasswordHash()));}
 @Test void resetRejectsWrongPhone(){Customer c=new Customer(customerRole,"A","a@b.com","0837777777",encoder.encode("OldPass@123"));when(customers.findByEmailIgnoreCase("a@b.com")).thenReturn(Optional.of(c));ApiException e=assertThrows(ApiException.class,()->service.resetPassword(new ResetPasswordRequest("a@b.com","0900000000","NewPass@123")));assertEquals(HttpStatus.BAD_REQUEST,e.status());}
}

